import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"原子操作","link":"/api/SIMD-API/basic_api/atomic_operations/atomic_operations"},{"text":"SetAtomicMin(ISASI)","link":"/api/SIMD-API/basic_api/atomic_operations/SetAtomicMin_ISASI"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/atomic_operations/SetAtomicMin_ISASI.md","filePath":"api/SIMD-API/basic_api/atomic_operations/SetAtomicMin_ISASI.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),c={name:"api/SIMD-API/basic_api/atomic_operations/SetAtomicMin_ISASI.md"};function t(i,s,e,o,d,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>SetAtomicMin(ISASI)<span id="ZH-CN_TOPIC_0000001637481306"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_set_atomic_intf.h&quot;</code>。</p><p>设置后续搬运到GM的数据是否执行原子比较：将待拷贝的内容和GM已有内容进行比较，然后将最小值写入GM。SetAtomicMin接口可通过设置模板参数来设定不同的数据类型。</p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetAtomicMin</span><span class="p">()</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>设定不同的原子最小操作数据类型。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>支持的数据类型为int8_t、int16_t、half、bfloat16_t、int32_t、float。</p><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT，支持的数据通路为UB/L0C Buffer-&gt;GM。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据通路为UB/L0C Buffer/L1 Buffer-&gt;GM。</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据通路为UB/L0C Buffer/L1 Buffer-&gt;GM。</li></ul></div><ul><li>使用完后，建议通过<a href="DisableDmaAtomic.html">DisableDmaAtomic</a>关闭原子最小操作，以免影响后续相关功能。</li><li>该接口执行前不会自动清零GM数据。开发者需根据算子逻辑判断是否清零，如需清零，请在执行前手动完成。</li><li>SetAtomicMin内部已集成与<a href="SetAtomicType.html">SetAtomicType</a>相同的功能。建议调用上述接口时，通过设置模板参数显式指定原子操作的数据类型，无需额外调用SetAtomicType接口。</li></ul><h2 id="调用示例">调用示例<span id="section177231425115410"></span><a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;kernel_operator.h&quot;</span>

<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">SIZE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CopyIn</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">queueSrc</span><span class="p">.</span><span class="n">AllocTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// 清空原子操作的状态</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DisableDmaAtomic</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">SIZE</span><span class="p">);</span>
<span class="w">    </span><span class="n">queueSrc</span><span class="p">.</span><span class="n">EnQue</span><span class="p">(</span><span class="n">srcLocal</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 核间同步</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">SyncAll</span><span class="p">();</span>
<span class="p">}</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CopyOut</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">queueSrc</span><span class="p">.</span><span class="n">DeQue</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// 开启原子MIN模式，3个核取最小值</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">SetAtomicMin</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">SIZE</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 关闭原子操作</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DisableDmaAtomic</span><span class="p">();</span>
<span class="w">    </span><span class="n">queueSrc</span><span class="p">.</span><span class="n">FreeTensor</span><span class="p">(</span><span class="n">srcLocal</span><span class="p">);</span>
<span class="p">}</span>

<span class="cm">/*</span>
<span class="cm">每个核的输入数据为: </span>
<span class="cm">Src0: [1,1,1,1,1,...,1] // 256个1</span>
<span class="cm">Src1: [2,2,2,2,2,...,2] // 256个2</span>
<span class="cm">最终输出数据: [1,1,1,1,1,...,1] // 256个1</span>
<span class="cm">*/</span>
</code></pre></div><p>完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/06_atomic/data_movement_with_atomic_operations">DataMovementWithAtomicOperations样例</a>。</p></article></div>`,1)])])}const _=a(c,[["render",t]]);export{A as __pageData,_ as default};
